<?php
declare(strict_types=1);
require_once __DIR__.'/../../src/manuals/ManualLibrary.php';
use FAS\Manuals\ManualLibrary;
use FAS\Manuals\ManualStorage;
$checks=0;
function check($condition,$message){global $checks;if(!$condition)throw new RuntimeException('FAIL: '.$message);$checks++;echo "PASS $message\n";}
function rejects(callable $fn,$message){try{$fn();}catch(Throwable $e){check(true,$message);return;}check(false,$message);}
$tmp=sys_get_temp_dir().'/fas-manuals-'.bin2hex(random_bytes(8));mkdir($tmp);mkdir($tmp.'/web');mkdir($tmp.'/private');
$db=new PDO('sqlite:'.$tmp.'/fixture.sqlite',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$db->exec('PRAGMA foreign_keys=ON');
check(!ManualLibrary::installed($db),'missing schema is not initialized by read');
ManualLibrary::install($db);check(ManualLibrary::installed($db),'explicit schema initialization');ManualLibrary::install($db);check(ManualLibrary::installed($db),'initialization idempotent');
$authorized=true;$repo=new ManualLibrary($db,function($actor,$action)use(&$authorized){return $authorized&&$actor===42;});
$input=ManualLibrary::blank()+[];$input['title']='Synthetic Workshop Reference';$input['manufacturer']='Example Mfg';$input['model']='Model ZX';$input['years']='2026';$input['description']='Synthetic test only. Torque and assembly illustrations.';
$storage=new ManualStorage($tmp.'/private',$tmp.'/web');
file_put_contents($tmp.'/test.pdf',"%PDF-1.4\n1 0 obj << /Type /Catalog >> endobj\n%%EOF\n");
$file=$storage->importLocal($tmp.'/test.pdf');check($storage->verifiedPath($file)!=='','PDF identity stored and verified');
rejects(fn()=>new ManualStorage($tmp.'/web',$tmp.'/web'),'webroot storage denied');
mkdir($tmp.'/web/nested');rejects(fn()=>new ManualStorage($tmp.'/web/nested',$tmp.'/web'),'nested public storage denied');
rejects(fn()=>new ManualStorage($tmp,$tmp.'/web'),'storage ancestor of webroot denied');
symlink($tmp.'/private',$tmp.'/linked');rejects(fn()=>new ManualStorage($tmp.'/linked',$tmp.'/web'),'symlinked storage denied');
file_put_contents($tmp.'/html.pdf','<script>alert(1)</script>');rejects(fn()=>$storage->importLocal($tmp.'/html.pdf'),'renamed non-PDF denied');
rejects(fn()=>$storage->acceptUpload(['error'=>0,'tmp_name'=>$tmp.'/test.pdf']),'non-HTTP file refused by upload method');
rejects(fn()=>$storage->verifiedPath(['key'=>'../../test.pdf','bytes'=>1,'sha256'=>str_repeat('a',64)]),'PDF traversal denied');
$manual=$repo->create($input,$file,42,str_repeat('a',48));check($manual['revision']===1,'upload creates revision one');check($repo->getPublished($manual['id'])===null,'new upload remains private');check($repo->searchPublished()['total']===0,'draft absent from public search');
$retry=$repo->create($input,$file,42,str_repeat('a',48));check($retry['id']===$manual['id']&&$retry['revision']===1,'repeated identical upload is idempotent');
$changed=$input;$changed['title']='Changed';rejects(fn()=>$repo->create($changed,$file,42,str_repeat('a',48)),'reuse with changed payload conflicts');
rejects(fn()=>$repo->create($input,$file,1,str_repeat('b',48)),'wrong actor cannot create');
rejects(fn()=>$repo->save(1,1,$input,'publish',42),'uncleared rights cannot publish');
$input['rights']='cleared';rejects(fn()=>$repo->save(1,1,$input,'publish',42),'clearance requires evidence and review');
$input['rights_note']='Synthetic original created by test suite';rejects(fn()=>$repo->save(1,1,$input,'publish',42),'publishing requires explicit review');
$input['reviewed']=true;$published=$repo->save(1,1,$input,'publish',42);check($published['revision']===2,'publish changes one revision');
$public=$repo->getPublished(1);check($public['metadata']['title']===$input['title'],'public snapshot available');check(!isset($public['metadata']['rights_note'])&&!isset($public['metadata']['source_url']),'private rights evidence excluded');
$result=$repo->searchPublished('ZX torque','Example Mfg');check($result['total']===1,'manufacturer and multi-term model search');check(!isset($result['items'][0]['file']),'catalog contains no private file identifiers');check($result['manufacturers'][0]['total']===1,'manufacturer facet count');
check($repo->searchPublished('%')['total']===0,'LIKE percent escaped');check($repo->searchPublished('_')['total']===0,'LIKE underscore escaped');check($repo->searchPublished('not found')['total']===0,'unknown text no matches');
rejects(fn()=>$repo->save(1,1,$input,'draft',42),'stale revision rejected');
$draft=$input;$draft['title']='Private updated title';$saved=$repo->save(1,2,$draft,'draft',42);check($repo->getPublished(1)['metadata']['title']===$input['title'],'draft edits leave reviewed snapshot intact');
$draft['rights']='restricted';$repo->save(1,3,$draft,'draft',42);check($repo->getPublished(1)===null,'rights restriction immediately withdraws snapshot');check($repo->searchPublished()['total']===0,'withdrawn manual removed from facets and search');
$repo->save(1,4,$input,'publish',42);$repo->save(1,5,[],'withdraw',42);check($repo->getPublished(1)===null,'explicit withdraw removes access');
check((int)$db->query('SELECT count(*) FROM manual_history')->fetchColumn()===6,'audit history has each successful revision only');
$authorized=false;rejects(fn()=>$repo->getAdmin(1,42),'revoked active actor cannot read private drafts');rejects(fn()=>$repo->save(1,6,$input,'publish',42),'revoked active actor cannot publish');$authorized=true;
rejects(fn()=>ManualLibrary::validate(array_replace($input,['title'=>['x']])),'malformed input shape rejected');
rejects(fn()=>ManualLibrary::validate(array_replace($input,['title'=>"bad\x00title"])),'control bytes rejected');
rejects(fn()=>ManualLibrary::validate(array_replace($input,['source_url'=>'javascript:alert(1)'])),'unsafe source scheme rejected');
rejects(fn()=>ManualLibrary::validate(array_replace($input,['source_url'=>'https://secret:pass@example.org/'])),'credentials in source reference rejected');
rejects(fn()=>ManualLibrary::validate(array_replace($input,['manufacturer'=>str_repeat('a',81)])),'metadata length bounded');
file_put_contents($storage->verifiedPath($file),'X',FILE_APPEND);rejects(fn()=>$storage->verifiedPath($file),'changed stored PDF fails integrity');
$db->exec('ALTER TABLE manuals ADD COLUMN unexpected TEXT');rejects(fn()=>ManualLibrary::installed($db),'unexpected schema rejected');
echo "\n$checks checks passed. Synthetic fixture only: $tmp\n";
